def test_get_context(self):
    tl1 = tlocus('GRCh37')
    tl2 = tlocus('GRCh38')
    types_and_rgs = [([tint32, tint64, tfloat32, tfloat64, tstr, tbool, tcall, tinterval(tset(tint32)), tdict(tstr, tarray(tint32)), tndarray(tstr, 1), tstruct(), tstruct(x=tint32, y=tint64, z=tarray(tset(tstr))), ttuple(tstr, tint32), ttuple()], set()), ([tl1, tinterval(tl1), tdict(tstr, tl1), tndarray(tl1, 2), tinterval(tl1), tset(tinterval(tl1)), tstruct(a=tint32, b=tint32, c=tarray(tl1)), ttuple(tarray(tint32), tl1, tstr, tint32, tbool)], {'GRCh37'}), ([tdict(tl1, tl2), ttuple(tarray(tl2), tl1, tstr, tint32, tbool)], {'GRCh37', 'GRCh38'})]
    for types, rgs in types_and_rgs:
        for t in types:
            self.assertEqual(t.get_context().references, rgs)
